<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Customer;use App\Support\BusinessAccess;use Illuminate\Http\Request;
class CustomerController extends Controller{
 public function index(Request $r){$q=Customer::where('business_id',BusinessAccess::id($r));BusinessAccess::scopeBranch($q,$r);if($r->filled('status')){if($r->status==='due')$q->where('current_due','>',0);if($r->status==='overdue')$q->where('current_due','>',0)->whereDate('due_since','<',now()->subDays(30));}if($r->filled('search'))$q->where(fn($x)=>$x->where('name','like','%'.$r->search.'%')->orWhere('mobile','like','%'.$r->search.'%'));return response()->json(['data'=>$q->latest()->paginate($r->integer('per_page',20))]);}
 public function store(Request $r){BusinessAccess::requireRole($r,['owner','manager','accountant','super_admin']);$business=BusinessAccess::id($r);$data=$r->validate(['branch_id'=>['nullable','integer','exists:branches,id'],'name'=>['required','string','max:160'],'contact_person'=>['nullable','string','max:120'],'mobile'=>['nullable','string','max:20'],'address'=>['nullable','string'],'credit_limit'=>['nullable','numeric','min:0']]);$branch=$data['branch_id']??$r->user()->branch_id;if($branch)BusinessAccess::branch($r,$branch);return response()->json(['data'=>Customer::create([...$data,'branch_id'=>$branch,'business_id'=>$business])],201);}
 public function show(Request $r,Customer $customer){$this->authorizeCustomer($r,$customer);return response()->json(['data'=>$customer,'aging'=>$this->aging($customer)]);}
 public function update(Request $r,Customer $customer){BusinessAccess::requireRole($r,['owner','manager','accountant','super_admin']);$this->authorizeCustomer($r,$customer);$data=$r->validate(['branch_id'=>['nullable','integer','exists:branches,id'],'name'=>['sometimes','string','max:160'],'contact_person'=>['nullable','string','max:120'],'mobile'=>['nullable','string','max:20'],'address'=>['nullable','string'],'credit_limit'=>['sometimes','numeric','min:0'],'is_active'=>['sometimes','boolean']]);if(!empty($data['branch_id']))BusinessAccess::branch($r,$data['branch_id']);$customer->update($data);return response()->json(['data'=>$customer->fresh()]);}
 public function ledger(Request $r,Customer $customer){$this->authorizeCustomer($r,$customer);return response()->json(['data'=>$customer->ledgers()->latest('entry_date')->paginate($r->integer('per_page',50)),'aging'=>$this->aging($customer)]);}
 private function authorizeCustomer(Request $r,Customer $customer):void{abort_unless($customer->business_id===BusinessAccess::id($r),403);if($customer->branch_id)BusinessAccess::branch($r,$customer->branch_id);}
 private function aging(Customer $customer):array{$days=$customer->due_since?$customer->due_since->diffInDays(now()):0;return['due'=>$customer->current_due,'due_since'=>$customer->due_since,'days'=>$days,'bucket'=>$days<=30?'0-30':($days<=60?'31-60':($days<=90?'61-90':'90+'))];}
}
